"""Record verified export evidence without claiming listening or user acceptance."""
from pathlib import Path
import json,yaml,hashlib
ROOT=Path(__file__).resolve().parents[3];SID='hb-c10-konsstympning';EP=ROOT/'studio/episodes'/SID;MEDIA=ROOT/'studio/media'/SID
script=yaml.safe_load((EP/'script.yaml').read_text());render=json.loads((EP/'render.json').read_text());check=json.loads((EP/'render-check.json').read_text());coverage=json.loads((EP/'picture-coverage.json').read_text());assert render['sha256']==check['sha256']==hashlib.sha256((ROOT/render['output']).read_bytes()).hexdigest();assert coverage['picture_fraction']==1
metrics=json.loads((MEDIA/'narration/metrics.json').read_text());asr={a['file']:a for a in json.loads((MEDIA/'narration/asr.json').read_text())};assert len(metrics)==len(asr)==11
for m in metrics:assert asr[m['path']]['sha256']==hashlib.sha256((ROOT/m['path']).read_bytes()).hexdigest()
(EP/'audio-diagnostics.json').write_text(json.dumps(dict(section_id=SID,selected_clips=11,all_current_wav_hashes_checked=True,listening=False,diagnostic_priorities=['Swedish medical compounds könsstympning,blygdläpparna,plastikkirurg and läkarremiss differ in ASR spelling; check pronunciation during complete-video review.'],records=[dict(sentence_id=m['sentence_id'],tts_input=m['text'],asr_text=asr[m['path']]['asr_text']) for m in metrics]),ensure_ascii=False,indent=2)+'\n')
report=dict(section_id=SID,status='preview_ready',output=render['output'],seconds=render['seconds'],sha256=render['sha256'],source_section_sha256=script['source_section_sha256'],translation_file_sha256=script['translation_file_sha256'],pairs=11,actual_body_picture_fraction=1,distinct_pictures=11,photographs=3,original_diagrams=8,full_decode='passed',encoded_audio_correlation=check['encoded_audio_matches_mix']['correlation'],sampled_export_frames=['export-frame-07.png','export-frame-12.png'],planned_visual_review=['opening bilingual title','pregnancy-risk schematic','actual healthcare photograph','all11pictures contact sheet'],phone_preview='640x360 resized exported frame07 inspected; no physical device playback',whole_video_listening=False,physical_device_playback=False,user_acceptance=False,issues=['Medical compound pronunciation and voice/music balance remain whole-video listening priorities.'])
(EP/'production-handoff.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n');b=yaml.safe_load((EP/'brief.yaml').read_text());b.update(production_status='preview_ready',output_path=render['output'],issues=['Verified complete preview; whole-video listening and user acceptance pending.']+report['issues']);(EP/'brief.yaml').write_text(yaml.safe_dump(b,allow_unicode=True,sort_keys=False,width=100))
(EP/'review.md').write_text(f'''# Episode review\n\nSection ID: {SID}\n\nProducer/date: Chapter 10 worker, 2026-11-03.\n\nPreview: `{render['output']}` — 2:42.417 at 1920×1080/24fps.\n\n- [x] All 11 exact source sentences and current reviewed Russian records retained once, in stored order. Current chapter-heading review and provenance checks pass.\n- [x] All 11 local F1 clips retained with exact inputs/settings, measured durations, current WAV hashes and ASR diagnostics.\n- [x] All planned cards fit at default 48/40 fonts, including the long bilingual opening. Sampled 1080p frames and a 640×360 resized exported frame were inspected without clipping.\n- [x] All 11 foreground pictures are distinct and source-relevant: three licensed healthcare-object/building photographs and eight individually composed non-graphic diagrams. Full body picture coverage is 100%.\n- [x] No real photographed person is identified as a survivor. Healthcare buildings are illustrative settings, not assertions that particular procedures are offered there. No fabricated anatomical detail, clinical guarantee or additional procedure instruction.\n- [x] Actual source publisher credits were derived from sources.yaml; matching complete sidecar credits are retained.\n- [x] Complete export decode passed: {check['decoded_video_frames']} frames, {check['decoded_audio_seconds']} seconds audio. Current encoded mix correlation {check['encoded_audio_matches_mix']['correlation']:.6f}.\n- [x] Continuous opening/background-boundary motion checks passed and are bound to the current export hash.\n- [ ] Whole-video pronunciation/accent and music balance listened to.\n- [ ] Headphone/speaker checks or physical phone/laptop playback.\n- [ ] Complete video watched/heard end to end and accepted by the user.\n\nASR spelling differs for some Swedish medical compounds; these are documented listening priorities, not proof of defective or correct pronunciation. No speculative repeated retakes.\n\nExport SHA-256: `{render['sha256']}`. No commit or upload.\n''')
print(json.dumps(report,ensure_ascii=False))
